<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;
class Automation extends Model{protected $fillable=['organization_id','name','description','status','enabled','version','created_by','updated_by','last_executed_at'];protected $casts=['enabled'=>'boolean','last_executed_at'=>'datetime'];public function organization(){return $this->belongsTo(Organization::class);}public function creator(){return $this->belongsTo(User::class,'created_by');}public function updater(){return $this->belongsTo(User::class,'updated_by');}public function triggers(){return $this->hasMany(AutomationTrigger::class);}public function conditions(){return $this->hasMany(AutomationCondition::class)->orderBy('position');}public function actions(){return $this->hasMany(AutomationAction::class)->orderBy('position');}public function schedules(){return $this->hasMany(AutomationSchedule::class);}public function executions(){return $this->hasMany(AutomationExecution::class);}public function operationalEvents(){return $this->hasMany(OperationalEvent::class);}public function collaborators(){return $this->hasMany(ResourceCollaborator::class,'resource_id')->where('resource_type','automation');}}
